        <tr><th>Grado</th><th>Luz</th><th>Oscuridad</th><th>Maná</th></tr>
        <tr><td>Impresión</td><td>Alborín</td><td>Umbrín</td><td>Míril</td></tr>
        <tr><td>Consolidación</td><td>Cendal</td><td>Drevak</td><td>Tessar</td></tr>
        <tr><td>Especialización</td><td>Arista</td><td>Náxide</td><td>Veyla</td></tr>
        <tr><td>Integración</td><td>Elarca</td><td>Korvath</td><td>Nymor</td></tr>
